    { title = "Wing Buffet", flags = 1, spell = 23339,
      body = "Ebonroc buffets the area before him with his wings, inflicting Physical damage, knocking players back and reducing their threat." },
  },
  [11981] = { -- Flamegor
    { title = "Frenzy", flags = 2048, spell = 23342,
      body = "Flamegor periodically enters a frenzy, increasing his attack speed. It can be soothed by a hunter's Tranquilizing Shot." },
    { title = "Shadow Flame", flags = 32, spell = 22539,
