  },
  [14020] = { -- Chromaggus
    { title = "Brood Affliction", flags = 32, spell = 23153,
      body = "Chromaggus afflicts the raid with Brood Afflictions of five colors. A player carrying all five mutates into a Chromatic Drakonid, so afflictions must be grouped and cleansed carefully." },
    { title = "Time Lapse", flags = 32, spell = 23310,
