  },
  [11583] = { -- Nefarian
    { title = "Shadow Flame", flags = 32, spell = 22539,
      body = "Nefarian breathes shadowflame, inflicting catastrophic Shadow damage to all enemies in a wide arc before him." },
    { title = "Class Calls", flags = 32, spell = 0,
      body = "Throughout the final phase Nefarian shouts mocking commands at specific classes — turning warriors berserk, banishing hunters' ranged weapons, polymorphing the raid's mages, and more — each disrupting that class for several seconds." },
    { title = "Bellowing Roar", flags = 32, spell = 22686,
      body = "Nefarian lets out a bellowing roar, causing the entire raid to flee in fear." },
    { title = "Tail Lash", flags = 0, spell = 23364,
      body = "Nefarian lashes his tail, inflicting Physical damage and stunning enemies standing behind him." },
    { title = "Cleave", flags = 0, spell = 22540,
      body = "Nefarian cleaves all enemies in front of him for heavy Physical damage." },
  },

  -- Onyxia's Lair (instance 249) — raid
  [10184] = { -- Onyxia
    { title = "Deep Breath", flags = 16, spell = 17086,
      body = "Onyxia inhales deeply and exhales a wall of fire across the length of the cavern, inflicting catastrophic Fire damage to any caught in its path." },
    { title = "Flame Breath", flags = 0, spell = 18435,
      body = "Onyxia breathes a cone of fire before her, inflicting heavy Fire damage to all enemies caught in it." },
