      body = "Below 30% health, Huhuran goes berserk, unleashing relentless torrents of poison on the entire raid until she falls." },
    { title = "Noxious Poison", flags = 512, spell = 26053,
      body = "Huhuran sprays a noxious poison, inflicting Nature damage over time to those it strikes." },
    { title = "Wyvern Sting", flags = 512, spell = 19386,
      body = "Huhuran stings a player, sending them into a poisoned slumber until the venom runs its course." },
  },
